(function () {
let unloadListenerAdded = false;
function initParallax(root) {
if (!root || root.dataset.peInitialized) {
return;
}
root.dataset.peInitialized = "1";
if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") {
return;
}
if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
return;
}
gsap.registerPlugin(ScrollTrigger);
ScrollTrigger.config({ limitCallbacks: true, ignoreMobileResize: true });
const svg = root.querySelector("svg");
const scrollElement = root.querySelector(".pe-parallax__scroll");
if (!svg || !scrollElement) {
return;
}
const q = gsap.utils.selector(root);
const set = function (selector, vars) {
gsap.set(q(selector), vars);
};
const makeScrollTrigger = function (timeline, start, end, scrub) {
ScrollTrigger.create({
animation: timeline,
trigger: scrollElement,
start: start,
end: end,
scrub: scrub
});
};
const speed = 100;
const height = svg.getBBox().height;
set("#h2-1", { opacity: 0 });
set("#bg_grad", { attr: { cy: "-50" } });
set("#dinoL, #dinoR", { y: 80 });
set("#dinoL", { x: -10 });
const mm = gsap.matchMedia();
mm.add("(max-width: 1922px)", () => {
set("#cloudStart-L, #cloudStart-R", { x: 10, opacity: 1 });
});
const scene1 = gsap.timeline();
makeScrollTrigger(scene1, "top top", "45% 100%", 3);
scene1.to(q("#h1-1"), { y: 3 * speed, x: 1 * speed, scale: 0.9, ease: "power1.in" }, 0);
scene1.to(q("#h1-2"), { y: 2.6 * speed, x: -0.6 * speed, ease: "power1.in" }, 0);
scene1.to(q("#h1-3"), { y: 1.7 * speed, x: 1.2 * speed }, 0.03);
scene1.to(q("#h1-4"), { y: 3 * speed, x: 1 * speed }, 0.03);
scene1.to(q("#h1-5"), { y: 2 * speed, x: 1 * speed }, 0.03);
scene1.to(q("#h1-6"), { y: 2.3 * speed, x: -2.5 * speed }, 0);
scene1.to(q("#h1-7"), { y: 5 * speed, x: 1.6 * speed }, 0);
scene1.to(q("#h1-8"), { y: 3.5 * speed, x: 0.2 * speed }, 0);
scene1.to(q("#h1-9"), { y: 3.5 * speed, x: -0.2 * speed }, 0);
scene1.to(q("#cloudsBig-L"), { y: 4.5 * speed, x: -0.2 * speed }, 0);
scene1.to(q("#cloudsBig-R"), { y: 4.5 * speed, x: -0.2 * speed }, 0);
scene1.to(q("#cloudStart-L"), { x: -300 }, 0);
scene1.to(q("#cloudStart-R"), { x: 300 }, 0);
scene1.to(q("#info"), { y: 8 * speed }, 0);
gsap.set(q("#bird"), { opacity: 1 });
var birdIdle = gsap.to(q("#bird"), {
y: -7,
rotation: 1.5,
duration: 2.6,
ease: "sine.inOut",
yoyo: true,
repeat: -1,
transformOrigin: "50% 50%"
});
gsap.fromTo(
q("#bird"),
{ y: 0, x: 0, rotation: 0, opacity: 1 },
{
y: -320,
x: 750,
ease: "power2.in",
scrollTrigger: {
trigger: scrollElement,
start: "15% top",
end: "55% 100%",
scrub: 3,
onEnter: function () {
birdIdle.kill();
},
onLeave: function () {
gsap.to(q("#bird"), { opacity: 0, duration: 0.3 });
}
}
}
);
const clouds = gsap.timeline();
makeScrollTrigger(clouds, "top top", "70% 100%", 1);
clouds.to(q("#cloud1"), { x: 500 }, 0);
clouds.to(q("#cloud2"), { x: 1000 }, 0);
clouds.to(q("#cloud3"), { x: -1000 }, 0);
clouds.to(q("#cloud4"), { x: -700, y: 25 }, 0);
const sun = gsap.timeline();
makeScrollTrigger(sun, "1% top", "2150 100%", 2);
sun.fromTo(q("#bg_grad"), { attr: { cy: "-50" } }, { attr: { cy: "330" } }, 0);
sun.to(q("#bg_grad stop:nth-child(2)"), { attr: { offset: "0.15" } }, 0);
sun.to(q("#bg_grad stop:nth-child(3)"), { attr: { offset: "0.18" } }, 0);
sun.to(q("#bg_grad stop:nth-child(4)"), { attr: { offset: "0.25" } }, 0);
sun.to(q("#bg_grad stop:nth-child(5)"), { attr: { offset: "0.46" } }, 0);
sun.to(q("#bg_grad stop:nth-child(6)"), { attr: { "stop-color": "#c8c4bc" } }, 0);
const scene2 = gsap.timeline();
makeScrollTrigger(scene2, "15% top", "40% 100%", 3);
scene2.fromTo(q("#h2-1"), { y: 500, opacity: 0 }, { y: 0, opacity: 1 }, 0);
scene2.fromTo(q("#h2-2"), { y: 500 }, { y: 0 }, 0.1);
scene2.fromTo(q("#h2-3"), { y: 700 }, { y: 0 }, 0.1);
scene2.fromTo(q("#h2-4"), { y: 700 }, { y: 0 }, 0.2);
scene2.fromTo(q("#h2-5"), { y: 800 }, { y: 0 }, 0.3);
scene2.fromTo(q("#h2-6"), { y: 900 }, { y: 0 }, 0.3);
set("#bats", { transformOrigin: "50% 50%" });
var ufoEntered = false;
var ufoTL = gsap.timeline();
ufoTL
.fromTo(q("#bats"), { opacity: 0, y: 280, scale: 0.5 }, { opacity: 1, y: 0, scale: 1, ease: "power2.out", duration: 0.45 })
.to(q("#bats"), { opacity: 0, y: -350, x: 60, scale: 0.3, ease: "power3.in", duration: 0.55 });
ScrollTrigger.create({
animation: ufoTL,
trigger: scrollElement,
start: "42% top",
end: "72% 100%",
scrub: 3,
onEnter: function () {
if (!ufoEntered) {
ufoEntered = true;
gsap.to(q("#bats .space-obj"), { rotation: 4, yoyo: true, repeat: -1, duration: 3.5, ease: "sine.inOut", transformOrigin: "50% 50%" });
}
}
});
const sun2 = gsap.timeline();
makeScrollTrigger(sun2, "2000 top", "5000 100%", 2);
sun2.to(q("#sun"), { attr: { offset: "1.4" } }, 0);
sun2.to(q("#bg_grad stop:nth-child(2)"), { attr: { offset: "0.7" } }, 0);
sun2.to(q("#sun"), { attr: { "stop-color": "#f5f2e8" } }, 0);
sun2.to(q("#lg4 stop:nth-child(1)"), { attr: { "stop-color": "#484448" } }, 0);
sun2.to(q("#lg4 stop:nth-child(2)"), { attr: { "stop-color": "#22202a" } }, 0);
sun2.to(q("#bg_grad stop:nth-child(6)"), { attr: { "stop-color": "#2a2630" } }, 0);
set("#scene3", { y: height - 40, visibility: "visible" });
const sceneTransition = gsap.timeline();
makeScrollTrigger(sceneTransition, "60% top", "bottom 100%", 3);
sceneTransition.to(q("#h2-1"), { y: -height - 100, scale: 1.5, transformOrigin: "50% 50%" }, 0);
sceneTransition.to(q("#bg_grad"), { attr: { cy: "-80" } }, 0.0);
sceneTransition.to(q("#bg2"), { y: 0 }, 0);
const scene3 = gsap.timeline();
makeScrollTrigger(scene3, "70% 50%", "bottom 100%", 3);
scene3.fromTo(q("#h3-1"), { y: 300 }, { y: -550 }, 0);
scene3.fromTo(q("#h3-2"), { y: 800 }, { y: -550 }, 0.03);
scene3.fromTo(q("#h3-3"), { y: 600 }, { y: -550 }, 0.06);
scene3.fromTo(q("#h3-4"), { y: 800 }, { y: -550 }, 0.09);
scene3.fromTo(q("#h3-5"), { y: 1000 }, { y: -550 }, 0.12);
scene3.fromTo(q("#stars"), { opacity: 0 }, { opacity: 0.5, y: -500 }, 0);
scene3.fromTo(q("#arrow2"), { opacity: 0 }, { opacity: 0.7, y: -710 }, 0.25);
scene3.fromTo(q("#text2"), { opacity: 0 }, { opacity: 0.7, y: -710 }, 0.3);
scene3.to(q("#bg2-grad"), { attr: { cy: 600 } }, 0);
scene3.to(q("#bg2-grad"), { attr: { r: 500 } }, 0);
set("#fstar", { y: -400 });
const fstarTL = gsap.timeline();
ScrollTrigger.create({
animation: fstarTL,
trigger: scrollElement,
start: "4200 top",
end: "6000 bottom",
scrub: 2,
onEnter: function () {
set("#fstar", { opacity: 1 });
},
onLeave: function () {
set("#fstar", { opacity: 0 });
}
});
fstarTL.to(q("#fstar"), { x: -700, y: -250, ease: "power2.out" }, 0);
const starTweens = [
{ index: 1, delay: 0.8 },
{ index: 3, delay: 1.8 },
{ index: 5, delay: 1 },
{ index: 8, delay: 1.2 },
{ index: 11, delay: 0.5 },
{ index: 15, delay: 2 },
{ index: 17, delay: 1.1 },
{ index: 18, delay: 1.4 },
{ index: 25, delay: 1.1 },
{ index: 28, delay: 0.9 },
{ index: 30, delay: 1.3 },
{ index: 35, delay: 2 },
{ index: 40, delay: 0.8 },
{ index: 45, delay: 1.8 },
{ index: 48, delay: 1 }
];
starTweens.forEach(function (entry) {
gsap.fromTo(
q("#stars path:nth-of-type(" + entry.index + ")"),
{ opacity: 0.3 },
{ opacity: 1, duration: 0.3, repeat: -1, repeatDelay: entry.delay }
);
});
var grainEl = root.querySelector('#pe-grain feTurbulence');
if (grainEl) {
gsap.to(grainEl, {
attr: { seed: 24 },
duration: 2.0,
ease: "steps(24)",
repeat: -1,
repeatDelay: 0
});
}
var scratchEl = root.querySelector('#film-scratch');
if (scratchEl) {
var scratchCount = 3;
for (var s = 0; s < scratchCount; s++) {
(function spawnScratch(initialDelay) {
gsap.delayedCall(initialDelay, function loop() {
gsap.set(scratchEl, {
x: gsap.utils.random(10, 735),
scaleY: gsap.utils.random(0.3, 1),
transformOrigin: 'top center',
opacity: gsap.utils.random(0.5, 0.9)
});
gsap.to(scratchEl, {
opacity: 0,
duration: gsap.utils.random(0.04, 0.14),
ease: 'none',
onComplete: function () {
gsap.delayedCall(gsap.utils.random(1, 5), loop);
}
});
});
})(s * 1.2);
}
}
if (!unloadListenerAdded) {
window.addEventListener("beforeunload", function () {
window.scrollTo(0, 0);
});
unloadListenerAdded = true;
}
}
function initAll() {
document.querySelectorAll(".pe-parallax").forEach(initParallax);
}
function observeAll() {
if (!("IntersectionObserver" in window)) {
initAll();
return;
}
const observer = new IntersectionObserver(
function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
initParallax(entry.target);
observer.unobserve(entry.target);
}
});
},
{ rootMargin: "300px 0px" }
);
document.querySelectorAll(".pe-parallax").forEach(function (el) {
observer.observe(el);
});
}
if (document.readyState === "loading") {
document.addEventListener("DOMContentLoaded", observeAll);
} else {
observeAll();
}
})();
